WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_c_change'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '速度变化型追及', 'kp-trv-c-change', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "速度变化型追及"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "追及过程中，追击者的速度是分段变化的，或者被追者的速度在变。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“警察追小偷，警察跑了 5 分钟后累了，速度下降一半……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "永远盯着【两人之间的距离差距】！每一段变化，都在缩小或拉大这个差距。"}]}, {"type": "katexBlock", "attrs": {"content": "S_{初始差距} = \\Delta S_1(第一段缩小的距离) + \\Delta S_2 + ..."}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[算出开始追击那一刻的总差距 S差] --> B[算第一阶段(速度突变前), 快者追回了多少距离]\nB --> C[如果没追上, 算出剩余差距 = S差 - 已追回]\nC --> D[带着新的剩余差距, 进入第二阶段新速度体系]\nD --> E[用剩余差距 ÷ 新的速度差 = 第二阶段所需时间]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记是被追的人也在跑：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多考生算第二阶段时，只算警察用新速度跑剩余距离的时间。别忘了小偷也在跑！只要是追及问题，所有阶段计算时间的除数，永远必须是两人的【速度差】，绝对不是单人速度！"}]}]}]}$$ AS jsonb), NULL, '速度变化型追及的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "速度变化型追及"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_c_change", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
